export type MessageKey = keyof typeof messages;
export type MessageValues = Readonly<Record<string, string | number>>;
let currentLanguage: Language = "id";

export function isLanguage(value: unknown): value is Language {
  return value === "id" || value === "en";
}

export function getLanguage(): Language {
  return currentLanguage;
}

export function setLanguage(language: Language): void {
  if (!isLanguage(language)) throw new Error("Unsupported interface language.");
  currentLanguage = language;
}

export function languageLocale(language = currentLanguage): "id-ID" | "en-US" {
  return language === "id" ? "id-ID" : "en-US";
}

export function isMessageKey(value: string): value is MessageKey {
  return Object.prototype.hasOwnProperty.call(messages, value);
}

export function t(key: MessageKey, values: MessageValues = {}): string {
  const pair = messages[key];
  if (!pair) throw new Error(`Unknown translation key: ${key}`);
  return pair[currentLanguage === "id" ? 0 : 1].replace(/\{(\w+)\}/g, (_match, name: string) => {
    if (!Object.prototype.hasOwnProperty.call(values, name)) throw new Error(`Missing translation value ${name} for ${key}.`);
    return String(values[name]);
  });
}

export function createFormatters() {
  const locale = languageLocale();
  return {
    kg: new Intl.NumberFormat(locale, { minimumFractionDigits: 3, maximumFractionDigits: 3 }),
    grams: new Intl.NumberFormat(locale, { maximumFractionDigits: 3 }),
    score: new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 1 }),
    factor: new Intl.NumberFormat(locale, { minimumFractionDigits: 6, maximumFractionDigits: 6, useGrouping: false }),
    date: new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeStyle: "short" }),
  };
}

export function inputNumber(value: number): string {
  return currentLanguage === "id" ? String(value).replace(".", ",") : String(value);
}

