export function errorText(error: Error): string {
  if (currentLanguage === "id") return error.message;
  const translated = errorTranslations[error.message];
  if (translated !== undefined) return translated;
  const metadataHttp = /^Metadata model gagal dimuat \(HTTP (\d+)\)\.$/.exec(error.message);
  if (metadataHttp) return `Model metadata could not be loaded (HTTP ${metadataHttp[1]}).`;
  // Browser, library, and user-authored diagnostics retain their original detail.
  return error.message;
}

export function translateDocument(root: ParentNode): void {
  const attributes = [
    ["data-i18n", null], ["data-i18n-placeholder", "placeholder"],
    ["data-i18n-aria", "aria-label"], ["data-i18n-alt", "alt"], ["data-i18n-content", "content"],
  ] as const;
  for (const [marker, attribute] of attributes) {
    for (const element of root.querySelectorAll<HTMLElement>(`[${marker}]`)) {
      const key = element.getAttribute(marker);
      if (key === null || !isMessageKey(key)) throw new Error(`Invalid translation marker: ${key}`);
      if (attribute === null) element.textContent = t(key);
      else element.setAttribute(attribute, t(key));
    }
  }
  for (const element of root.querySelectorAll<HTMLElement>("[data-i18n-html]")) {
    const key = element.getAttribute("data-i18n-html");
    if (key === null || !isMessageKey(key) || /\{\w+\}/.test(messages[key][0])) {
      throw new Error(`Invalid static HTML translation marker: ${key}`);
    }
    element.innerHTML = t(key);
  }
  for (const template of root.querySelectorAll<HTMLTemplateElement>("template")) translateDocument(template.content);
}
